"use client";

import { useMemo, type ReactNode } from "react";
import { Button } from "@/components/ui/button";
import {
  DataGridBody,
  DataGridHeader,
  DataGridProvider,
  DataGridRoot,
  defineColumns,
  useDataGridActions,
} from "@/registry/default/components/data-grid/data-grid";
import { DataGridContextMenu, DataGridHeaderDropdown } from "@/registry/default/components/data-grid-context-menu/data-grid-context-menu";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 160, flex: 1, groupable: false },
  { id: "role", header: "Role", accessorKey: "role", type: "select", options: { choices: ["Admin", "User", "Editor", "Viewer", "Manager"] }, width: 110 },
  { id: "active", header: "Active", accessorKey: "active", type: "checkbox", width: 90 },
  { id: "age", header: "Age", accessorKey: "age", type: "number", width: 80, aggregate: "avg" },
  { id: "score", header: "Score", accessorKey: "score", type: "number", width: 90, aggregate: "sum" },
] as const);

function GroupControls(): ReactNode {
  const actions = useDataGridActions();
  return (
    <div className="flex gap-2">
      <Button size="sm" variant="outline" onClick={() => actions.expandAll()}>
        Expand all
      </Button>
      <Button size="sm" variant="outline" onClick={() => actions.collapseAll()}>
        Collapse all
      </Button>
      <Button size="sm" variant="outline" onClick={() => actions.setGroupBy(["role", "active"])}>
        Group by role, then active
      </Button>
      <Button size="sm" variant="outline" onClick={() => actions.setGroupBy([])}>
        Ungroup
      </Button>
    </div>
  );
}

/** Rows grouped by role. Each group row shows its row count and the average age and total score. Open a header menu to group by another column. */
export default function DataGridRowGroupingDemo(): ReactNode {
  const rows = useMemo(() => generateDemoRows(200), []);
  return (
    <div className="flex w-full flex-col gap-2">
      <DataGridProvider defaultData={rows} columns={columns} defaultGroupBy={["role"]}>
        <GroupControls />
        <div className="h-[380px] overflow-hidden rounded-md border border-border">
          <DataGridContextMenu className="flex h-full flex-col">
            <DataGridRoot aria-label="Employees by role" className="h-full rounded-[inherit] border-none" renderHeaderMenu={(ctx) => <DataGridHeaderDropdown {...ctx} />}>
              <DataGridHeader />
              <DataGridBody />
            </DataGridRoot>
          </DataGridContextMenu>
        </div>
      </DataGridProvider>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const ADJECTIVES = ["Eager", "Quick", "Silent", "Bold", "Swift"] as const;
const NOUNS = ["Eagle", "Lion", "Tiger", "Bear", "Wolf"] as const;

/** Generates `count` deterministic demo rows for example previews (seed 42, stable across renders). */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  for (let i = 0; i < count; i++) {
    rows.push({
      id: `row-${i}`,
      name: `${ADJECTIVES[Math.floor(next() * ADJECTIVES.length)]} ${NOUNS[Math.floor(next() * NOUNS.length)]}`,
      email: `user${i}@example.com`,
      age: Math.floor(next() * 50) + 18,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
